import{_ as t}from"./chunks/concept-diagram.Cp24n1VV.js";import{_ as o,o as a,c as r,a5 as i}from"./chunks/framework.CcrBcQWS.js";const g=JSON.parse('{"title":"Concept","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/concept.md","filePath":"software/concept.md","lastUpdated":1787021357000}'),n={name:"software/concept.md"};function l(s,e,c,d,m,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="concept" tabindex="-1">Concept <a class="header-anchor" href="#concept" aria-label="Permalink to &quot;Concept&quot;">​</a></h1><h2 id="system-diagram" tabindex="-1">System Diagram <a class="header-anchor" href="#system-diagram" aria-label="Permalink to &quot;System Diagram&quot;">​</a></h2><br><figure><img src="'+t+'" alt="RBQ software concept diagram"></figure><br><h2 id="sdk-overview" tabindex="-1">SDK Overview <a class="header-anchor" href="#sdk-overview" aria-label="Permalink to &quot;SDK Overview&quot;">​</a></h2><p>The <strong>RBQ SDK</strong> is built to provide developers with a flexible and scalable interface for working with the <strong>RBQ quadruped robot</strong>.</p><p>It supports both <strong>low-level control</strong> and <strong>high-level commands</strong>, so whether you&#39;re building your own controller or integrating the robot into an existing system, there&#39;s a suitable entry point.</p><h2 id="low-level-access" tabindex="-1">Low-Level Access <a class="header-anchor" href="#low-level-access" aria-label="Permalink to &quot;Low-Level Access&quot;">​</a></h2><p>The <strong>LV0 SDK</strong> offers direct access to the robot’s sensors and actuators.</p><p>It is intended for developers who need <strong>precise control</strong> and <strong>real-time feedback</strong> from the hardware.</p><h3 id="key-features" tabindex="-1">Key Features: <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features:&quot;">​</a></h3><ul><li>Read raw sensor data: IMU, joint encoders, etc.</li><li>Send joint-level commands: position, velocity, torque</li><li>Ideal for: <ul><li>Custom controller development</li><li>Low-latency real-time experiments</li><li>Research in locomotion control</li></ul></li></ul><h2 id="high-level-command-interface" tabindex="-1">High-Level Command Interface <a class="header-anchor" href="#high-level-command-interface" aria-label="Permalink to &quot;High-Level Command Interface&quot;">​</a></h2><p>The <strong>LV1 SDK</strong> provides a <strong>simplified interface</strong> to control the robot using predefined actions and commands, without needing to manage low-level details.</p><h3 id="key-features-1" tabindex="-1">Key Features: <a class="header-anchor" href="#key-features-1" aria-label="Permalink to &quot;Key Features:&quot;">​</a></h3><ul><li>Execute common motions and gait behaviors with a single command</li><li>Seamless integration with the <strong>RBQ APP</strong> command set</li><li>APIs available in: <ul><li>C/C++</li><li>Python</li><li>ROS2</li></ul></li><li>Ideal for: <ul><li>Application developers</li><li>System integration</li><li>Rapid prototyping with minimal setup</li></ul></li></ul><h2 id="supported-communication-interfaces" tabindex="-1">Supported Communication Interfaces <a class="header-anchor" href="#supported-communication-interfaces" aria-label="Permalink to &quot;Supported Communication Interfaces&quot;">​</a></h2><p>The SDK supports multiple communication protocols depending on your use case:</p><table><tr><th>Interface</th><th>Description</th></tr><tr><td>ROS2 SDK</td><td>For robotics developers in the ROS2 ecosystem</td></tr><tr><td>DDS SDK</td><td>For real-time, distributed communication using DDS</td></tr><tr><td>TCP / UDP</td><td>Lightweight direct packet communication for custom tools</td></tr></table>',20)])])}const f=o(n,[["render",l]]);export{g as __pageData,f as default};
